


export type CheckoutSettings = { /** Delivery methods a checkout offers when its creator names none: a checkout creation request that omits delivery_method_ids, and, when the order has items to deliver, a payment link without delivery_method_ids or an invoice checkout. Each checkout pins the methods when it is created. An explicit empty delivery_method_ids array on a checkout creation request overrides this default. */ "default_delivery_method_ids"?: Array<string>; /** Default lifetime in seconds for generic checkout sessions. Invoice checkout sessions instead use the fixed deadline of the active invoice public-link generation. Use an exact numeric string, not a floating-point number. Format: int64. */ "default_expires_in_seconds"?: string; "enabled_payment_options"?: Array<string>; /** Merchant default for hosted checkout promotion code entry. Object-level promotion_config.codes_enabled can override it for a session or payment link. */ "promotion_code_entry_enabled"?: boolean; /** Checkout reminder email: one email to a buyer who entered an email address in hosted checkout and left without paying. Merchant scope only. Effective settings default it to off with a 60 minute delay. */ "recovery_email"?: { /** Minutes to wait after the buyer last changed their email or phone before sending the reminder. Defaults to 60. Format: int32. minimum: 15. maximum: 1440. */ "delay_minutes"?: number; /** Whether Flint sends checkout reminders. Turning them on requires a business address on the merchant, which the reminder prints; without one the update returns CHECKOUT_RECOVERY_EMAIL_ADDRESS_REQUIRED. */ "enabled"?: boolean; }; "require_billing_address"?: boolean; "require_email"?: boolean; "require_phone"?: boolean; /** Whether hosted checkout offers buyers the option to save the card they type for faster checkout at this merchant. Merchant scope only. Effective settings default it to on. */ "saved_payment_details"?: { /** Whether hosted checkout shows buyers an unchecked option to save the card they type. A card is saved only when the buyer checks it and the payment succeeds, with usage on_session: Flint charges it only in checkouts the buyer completes, never for subscriptions, automatic invoices, or other charges without the buyer. Checkout never shows the option when customer accounts are merchant hosted, or for invoice, subscription, and return checkouts. */ "enabled"?: boolean; }; };
